{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic lacks customer-managed encryption",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The production notification topic does not specify kms_key_name, so messages are encrypted only with Google-managed keys rather than a customer-managed key."
    }
  ],
  "patched_code": "variable "pubsub_kms_key_name" {
  description = "Fully qualified resource name of the customer-managed Cloud KMS key used to encrypt the Pub/Sub topic."
  type        = string

  validation {
    condition     = length(trimspace(var.pubsub_kms_key_name)) > 0
    error_message = "pubsub_kms_key_name must be a non-empty Cloud KMS key resource name."
  }
}

resource "google_pubsub_topic" "notification_queue" {
  name         = "insurance-claims-processing-platform-pubsub-notifications"
  kms_key_name = var.pubsub_kms_key_name

  labels = {
    environment = "production"
    component   = "notifications"
  }
}
",
  "fix_summary": "Added a required, validated input for an existing customer-managed Cloud KMS key and configured the Pub/Sub topic to use it for encryption."
}
